-- --------------------------------------------------------
-- Struttura della tabella `products`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` VARCHAR(32) NOT NULL,
  `slug` VARCHAR(191) NOT NULL,
  `category` VARCHAR(32) NOT NULL,
  `destination_id` BIGINT UNSIGNED DEFAULT NULL,
  `destination_slug` VARCHAR(64) NOT NULL,
  `supplier_id` BIGINT UNSIGNED DEFAULT NULL,
  `title` VARCHAR(191) NOT NULL,
  `subtitle` VARCHAR(255) NOT NULL,
  `location` VARCHAR(191) NOT NULL,
  `price` INT NOT NULL,
  `unit` VARCHAR(32) NOT NULL DEFAULT 'giorno',
  `capacity` INT NOT NULL DEFAULT 2,
  `capacity_label` VARCHAR(64) NOT NULL,
  `featured` TINYINT(1) NOT NULL DEFAULT 0,
  `is_available` TINYINT(1) NOT NULL DEFAULT 1,
  `badge` VARCHAR(100) DEFAULT NULL,
  `subtype` VARCHAR(100) DEFAULT NULL,
  `lng` DECIMAL(10,6) NOT NULL,
  `lat` DECIMAL(10,6) NOT NULL,
  `map_x` DECIMAL(6,2) NOT NULL DEFAULT 50,
  `map_y` DECIMAL(6,2) NOT NULL DEFAULT 50,
  `description` LONGTEXT NOT NULL,
  `cancellation_policy` TEXT DEFAULT NULL,
  `images_json` LONGTEXT NOT NULL,
  `amenities_json` LONGTEXT NOT NULL,
  `services_included_json` LONGTEXT NOT NULL,
  `services_excluded_json` LONGTEXT NOT NULL,
  `rules_json` LONGTEXT NOT NULL,
  `specs_extra_json` LONGTEXT NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_code_unique` (`code`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_category_dest_idx` (`category`, `destination_slug`),
  KEY `products_supplier_idx` (`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dump dei dati per la tabella `products` (36 record)
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('1', 'vl-01', 'villa-smeralda-porto-cervo', 'villa', '1', 'costa-smeralda', '1', 'Villa Smeralda', '6 camere · 7 bagni · 480 m²', 'Porto Cervo, Costa Smeralda', '5500', 'notte', '8', '8 ospiti', '1', '1', 'VISTA MARE', 'Villa con Piscina', '9.529', '41.133', '52', '40', 'Sospesa sulla baia di Porto Cervo, Villa Smeralda unisce l''architettura mediterranea della Costa Smeralda a interni contemporanei firmati da uno studio milanese. Ogni camera si apre su terrazze private con vista sul mare color giada.

Il grande living con vetrate a tutta altezza scorre verso la piscina a sfioro e l''area pranzo esterna in granito locale, per cene al tramonto servite dallo staff dedicato.

La posizione, a cinque minuti dalla Piazzetta e dal porto vecchio, la rende la base ideale per un''esperienza completa tra mare, boutique e vita notturna.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-smeralda-porto-cervo/1.webp","/images/products/villa-smeralda-porto-cervo/2.webp","/images/products/villa-smeralda-porto-cervo/3.webp","/images/products/villa-smeralda-porto-cervo/4.webp"]', '["Piscina a sfioro","Vista mare panoramica","Aria condizionata","Wi-Fi ad alta velocità","Palestra privata","Cantina vini","Parcheggio per 4 auto","Sistema audio Sonos"]', '["Governante giornaliera","Concierge dedicato 7\/7","Cambio biancheria a giorni alterni","Utenze e climatizzazione"]', '["Chef privato (su richiesta)","Transfer da\/per aeroporto","Baby sitting"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":6,"beds":7,"bathrooms":7,"maxGuests":12,"sqm":480,"pool":true,"seaView":true,"staff":["Governante","Giardiniere","Concierge"],"chefAvailable":true,"depositAmount":8000,"rating":4.9,"reviewsCount":27,"locality":"Porto Cervo"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('2', 'vl-02', 'villa-pevero-bay', 'villa', '1', 'costa-smeralda', '1', 'Villa Pevero Bay', '7 camere · 8 bagni · 650 m²', 'Porto Cervo, Costa Smeralda', '8500', 'notte', '8', '8 ospiti', '1', '1', 'STAFF RESIDENTE', 'Villa con Piscina', '9.546', '41.121', '64', '48', 'Affacciata sul golfo del Pevero, questa tenuta di nuova costruzione è tra le proprietà più esclusive della costa: sette suite, spa privata con hammam e un parco di macchia mediterranea che digrada verso una caletta riservata.

Gli ambienti interni alternano pietra sarda, rovere e opere d''arte contemporanea. La zona living si apre su una terrazza di 300 mq con piscina riscaldata e lounge esterna.

Lo staff residente, con maggiordomo e chef su richiesta, garantisce un servizio da hotel cinque stelle nella privacy assoluta di una casa privata.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-pevero-bay/1.webp","/images/products/villa-pevero-bay/2.webp","/images/products/villa-pevero-bay/3.webp","/images/products/villa-pevero-bay/4.webp"]', '["Accesso privato al mare","Spa con hammam","Piscina riscaldata","Cinema privato","Eliporto convenzionato","Wi-Fi ad alta velocità","Cantina vini","Suite indipendente per staff"]', '["Maggiordomo residente","Governante giornaliera","Concierge dedicato 7\/7","Sicurezza notturna"]', '["Chef privato (su richiesta)","Sommelier per eventi","Transfer in elicottero"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":7,"beds":9,"bathrooms":8,"maxGuests":14,"sqm":650,"pool":true,"seaView":true,"staff":["Maggiordomo","Governante","Giardiniere","Sicurezza"],"chefAvailable":true,"depositAmount":12000,"rating":5,"reviewsCount":14,"locality":"Porto Cervo"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('3', 'vl-03', 'tenuta-arzachena', 'villa', '1', 'costa-smeralda', '2', 'Tenuta Arzachena', '5 camere · 5 bagni · 380 m²', 'Arzachena, Costa Smeralda', '2800', 'notte', '8', '8 ospiti', '0', '1', NULL, 'Villa con Piscina', '9.405', '41.068', '18', '42', 'Uno stazzo gallurese ristrutturato con rigore filologico, immerso in dodici ettari di vigneti e sughere tra Arzachena e la costa. Il fascino della campagna sarda a quindici minuti dalle spiagge del Pevero.

Cinque camere in pietra locale, una corte interna con pergolato per lunghi pranzi estivi e una piscina in travertino affacciata sulle vigne di Vermentino della tenuta.

Ideale per chi cerca autenticità senza rinunciare al servizio: la cantina della proprietà organizza degustazioni private e cene con prodotti del territorio.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/tenuta-arzachena/1.webp","/images/products/tenuta-arzachena/2.webp","/images/products/tenuta-arzachena/3.webp","/images/products/tenuta-arzachena/4.webp"]', '["Piscina in travertino","Vigneto e cantina propri","Corte interna con pergolato","Camino in pietra","Aria condizionata","Wi-Fi","Barbecue in muratura","Parcheggio privato"]', '["Pulizie giornaliere","Degustazione di benvenuto","Utenze"]', '["Chef privato (su richiesta)","Cene in vigna (su richiesta)","Transfer"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":5,"beds":6,"bathrooms":5,"maxGuests":10,"sqm":380,"pool":true,"seaView":false,"staff":["Governante","Cantiniere"],"chefAvailable":true,"depositAmount":4000,"rating":4.7,"reviewsCount":41,"locality":"Arzachena"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('4', 'vl-04', 'villa-ginestra-positano', 'villa', '2', 'costiera-amalfitana', '3', 'Villa Ginestra', '4 camere · 4 bagni · 320 m²', 'Positano, Costiera Amalfitana', '4200', 'notte', '8', '8 ospiti', '1', '1', 'VISTA MARE', 'Villa con Piscina', '14.488', '40.63', '30', '34', 'Aggrappata alla roccia sopra Positano, Villa Ginestra domina la costiera con una delle viste più fotografate del Mediterraneo: dalle terrazze a picco lo sguardo corre da Li Galli a Praiano.

Interni in maiolica vietrese e lino bianco, quattro camere con vista e una cucina professionale dove lo chef di casa prepara la colazione ogni mattina.

Il limoneto a terrazze e la piscina scavata nella roccia completano un rifugio raggiungibile in tre minuti a piedi dalla Spiaggia Grande, con servizio navetta interno per i bagagli.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-ginestra-positano/1.webp","/images/products/villa-ginestra-positano/2.webp","/images/products/villa-ginestra-positano/3.webp","/images/products/villa-ginestra-positano/4.webp"]', '["Terrazze vista mare","Piscina nella roccia","Limoneto privato","Maioliche d''epoca","Aria condizionata","Wi-Fi ad alta velocità","Navetta interna","Cucina professionale"]', '["Colazione preparata dallo chef","Governante giornaliera","Navetta per la spiaggia","Concierge dedicato"]', '["Pranzi e cene dello chef (su richiesta)","Transfer da\/per Napoli","Escursioni in barca"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":4,"beds":5,"bathrooms":4,"maxGuests":8,"sqm":320,"pool":true,"seaView":true,"staff":["Chef di casa","Governante"],"chefAvailable":true,"depositAmount":6000,"rating":4.9,"reviewsCount":33,"locality":"Positano"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('5', 'vl-05', 'palazzo-ravello', 'villa', '2', 'costiera-amalfitana', '3', 'Palazzo Ravello', '6 camere · 6 bagni · 540 m²', 'Ravello, Costiera Amalfitana', '6000', 'notte', '8', '8 ospiti', '1', '1', 'DIMORA STORICA', 'Villa con Piscina', '14.612', '40.649', '66', '26', 'Un palazzo nobiliare del Settecento nel cuore di Ravello, a pochi passi da Villa Rufolo: soffitti affrescati, chiostro privato e un giardino pensile che guarda il mare da trecento metri d''altezza.

Le sei suite conservano pavimenti originali in cotto napoletano e sono servite da un maggiordomo che cura ogni dettaglio, dal risveglio alla mise en place delle cene in giardino.

Nelle sere d''estate il belvedere privato diventa il palco ideale per concerti da camera e cene di gala fino a trenta ospiti.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/palazzo-ravello/1.webp","/images/products/palazzo-ravello/2.webp","/images/products/palazzo-ravello/3.webp","/images/products/palazzo-ravello/4.webp"]', '["Giardino pensile sul mare","Affreschi originali","Chiostro privato","Piscina panoramica","Ascensore","Wi-Fi","Sala musica con pianoforte","Spazi per eventi"]', '["Maggiordomo","Governante giornaliera","Concierge dedicato","Utenze"]', '["Chef privato (su richiesta)","Organizzazione eventi","Transfer"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":6,"beds":7,"bathrooms":6,"maxGuests":12,"sqm":540,"pool":true,"seaView":true,"staff":["Maggiordomo","Governante","Giardiniere"],"chefAvailable":true,"depositAmount":9000,"rating":4.8,"reviewsCount":19,"locality":"Ravello"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('6', 'vl-06', 'villa-lariana-bellagio', 'villa', '3', 'lago-di-como', '4', 'Villa Lariana', '6 camere · 7 bagni · 600 m²', 'Bellagio, Lago di Como', '7000', 'notte', '8', '8 ospiti', '1', '1', 'DARSENA PRIVATA', 'Villa con Piscina', '9.26', '45.988', '55', '34', 'Sulla punta di Bellagio, Villa Lariana è una dimora liberty del 1911 con parco secolare e darsena privata direttamente sul lago: l''indirizzo che ha reso celebre il ramo di Como.

Saloni con stucchi originali, sei suite affacciate sull''acqua e una veranda in ferro battuto dove viene servito l''aperitivo al tramonto, quando il lago si accende di rosa.

La darsena ospita il motoscafo della casa: il maggiordomo organizza traversate private verso Villa d''Este e i ristoranti stellati della sponda occidentale.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-lariana-bellagio/1.webp","/images/products/villa-lariana-bellagio/2.webp","/images/products/villa-lariana-bellagio/3.webp","/images/products/villa-lariana-bellagio/4.webp"]', '["Darsena privata","Parco secolare","Motoscafo della casa","Piscina riscaldata","Stucchi liberty originali","Wi-Fi ad alta velocità","Sala biliardo","Cantina vini"]', '["Maggiordomo","Governante giornaliera","Skipper del motoscafo","Concierge dedicato"]', '["Chef privato (su richiesta)","Carburante del motoscafo","Transfer da\/per Milano"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":6,"beds":8,"bathrooms":7,"maxGuests":12,"sqm":600,"pool":true,"seaView":false,"staff":["Maggiordomo","Governante","Skipper"],"chefAvailable":true,"depositAmount":10000,"rating":4.9,"reviewsCount":22,"locality":"Bellagio"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('7', 'vl-07', 'villa-cernobbio', 'villa', '3', 'lago-di-como', '4', 'Villa Cernobbio', '4 camere · 4 bagni · 300 m²', 'Cernobbio, Lago di Como', '3500', 'notte', '8', '8 ospiti', '0', '1', NULL, 'Dimora Storica', '9.073', '45.843', '24', '66', 'A due passi da Villa d''Este, una residenza ottocentesca ristrutturata con eleganza contemporanea: quattro camere, giardino all''italiana e vista aperta sul primo bacino del lago.

Gli interni firmati da un atelier comasco mescolano sete locali, marmi e pezzi di design; la cucina si apre su una terrazza coperta per colazioni sull''acqua.

Posizione perfetta per vivere il lago: imbarcadero a 200 metri, centro di Cernobbio a cinque minuti a piedi e Como raggiungibile in dieci minuti d''auto.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-cernobbio/1.webp","/images/products/villa-cernobbio/2.webp","/images/products/villa-cernobbio/3.webp","/images/products/villa-cernobbio/4.webp"]', '["Giardino all''italiana","Vista lago","Terrazza coperta","Aria condizionata","Wi-Fi ad alta velocità","Parcheggio privato","Sauna","Biciclette a disposizione"]', '["Pulizie giornaliere","Concierge su chiamata","Utenze"]', '["Chef privato (su richiesta)","Motoscafo con skipper (su richiesta)","Transfer"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":4,"beds":5,"bathrooms":4,"maxGuests":8,"sqm":300,"pool":false,"seaView":false,"staff":["Governante"],"chefAvailable":true,"depositAmount":5000,"rating":4.7,"reviewsCount":36,"locality":"Cernobbio"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('8', 'vl-08', 'villa-marinella-porto-rotondo', 'villa', '1', 'costa-smeralda', '1', 'Villa Marinella', '5 camere · 5 bagni · 420 m²', 'Porto Rotondo, Costa Smeralda', '4800', 'notte', '8', '8 ospiti', '1', '1', 'VISTA MARE', 'Villa con Piscina', '9.546', '41.031', '72', '60', 'Adagiata sulla collina che abbraccia il porticciolo di Porto Rotondo, Villa Marinella guarda il golfo di Marinella e l''Isola di Tavolara che chiude l''orizzonte a sud. Cinque camere luminose, tutte con accesso diretto al giardino mediterraneo.

Il living si apre senza soluzione di continuità sulla piscina a sfioro e su una terrazza in teak per le cene all''aperto, mentre un pergolato di gelsomino ripara l''angolo lounge dal sole del pomeriggio.

A pochi minuti a piedi dalla Piazzetta San Marco e dal molo, è la base perfetta per vivere Porto Rotondo tra aperitivi, boutique e uscite in barca.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-marinella-porto-rotondo/1.webp","/images/products/villa-marinella-porto-rotondo/2.webp","/images/products/villa-marinella-porto-rotondo/3.webp","/images/products/villa-marinella-porto-rotondo/4.webp"]', '["Piscina a sfioro","Vista sul golfo di Marinella","Giardino mediterraneo","Aria condizionata","Wi-Fi ad alta velocità","Barbecue e cucina esterna","Parcheggio per 3 auto","Sistema audio multiroom"]', '["Governante giornaliera","Concierge dedicato 7\/7","Cambio biancheria a giorni alterni","Utenze e climatizzazione"]', '["Chef privato (su richiesta)","Transfer da\/per aeroporto Olbia","Servizio spiaggia"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":5,"beds":6,"bathrooms":5,"maxGuests":10,"sqm":420,"pool":true,"seaView":true,"staff":["Governante","Giardiniere","Concierge"],"chefAvailable":true,"depositAmount":7000,"rating":4.8,"reviewsCount":24,"locality":"Porto Rotondo"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('9', 'vl-09', 'villa-tramonto-praiano', 'villa', '2', 'costiera-amalfitana', '3', 'Villa Tramonto', '4 camere · 4 bagni · 300 m²', 'Praiano, Costiera Amalfitana', '3800', 'notte', '8', '8 ospiti', '1', '1', 'VISTA MARE', 'Villa con Piscina', '14.524', '40.61', '40', '42', 'Praiano è il balcone da cui la Costiera guarda il sole calare dietro Positano, e Villa Tramonto ne occupa il punto più scenografico: una terrazza a strapiombo dove ogni sera il mare si tinge d''oro e di rosa.

Quattro camere in maiolica e calce bianca, una piscina a sfioro sospesa sul blu e un pergolato di bouganville sotto cui lo chef di casa serve la colazione con vista su Capri.

Una scalinata privata scende verso la caletta di Marina di Praia, mentre il centro del paese, con la sua chiesa maiolicata, è a pochi minuti a piedi.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-tramonto-praiano/1.webp","/images/products/villa-tramonto-praiano/2.webp","/images/products/villa-tramonto-praiano/3.webp","/images/products/villa-tramonto-praiano/4.webp"]', '["Terrazza vista tramonto","Piscina a sfioro sul mare","Pergolato di bouganville","Maioliche vietresi","Aria condizionata","Wi-Fi ad alta velocità","Accesso privato alla caletta","Cucina professionale"]', '["Colazione preparata dallo chef","Governante giornaliera","Concierge dedicato","Utenze e climatizzazione"]', '["Pranzi e cene dello chef (su richiesta)","Transfer da\/per Napoli","Escursioni in barca"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":4,"beds":5,"bathrooms":4,"maxGuests":8,"sqm":300,"pool":true,"seaView":true,"staff":["Chef di casa","Governante"],"chefAvailable":true,"depositAmount":5500,"rating":4.9,"reviewsCount":28,"locality":"Praiano"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('10', 'vl-10', 'villa-varenna', 'villa', '3', 'lago-di-como', '4', 'Villa Varenna', '5 camere · 5 bagni · 400 m²', 'Varenna, Lago di Como', '4500', 'notte', '8', '8 ospiti', '1', '1', 'DARSENA PRIVATA', 'Villa con Piscina', '9.284', '46.011', '66', '30', 'Sulla sponda orientale del lago, dove Varenna custodisce l''atmosfera più autentica del Lario, questa villa ottocentesca digrada verso l''acqua con un giardino a terrazze di ulivi, cipressi e limoni in vaso.

Cinque camere affacciate sul ramo di Lecco, saloni con pavimenti in seminato veneziano e una veranda a picco sul lago dove viene servito l''aperitivo mentre i battelli attraversano verso Bellagio.

La darsena privata ospita il motoscafo della casa: dal pontile si raggiungono in pochi minuti Villa Monastero e i ristoranti della sponda occidentale.', 'Cancellazione gratuita fino a 30 giorni dall''arrivo; entro 30 giorni trattenuto il 50% a copertura della proprietà.', '["/images/products/villa-varenna/1.webp","/images/products/villa-varenna/2.webp","/images/products/villa-varenna/3.webp","/images/products/villa-varenna/4.webp"]', '["Darsena e pontile privati","Giardino a terrazze sul lago","Veranda panoramica","Piscina riscaldata","Aria condizionata","Wi-Fi ad alta velocità","Camino nel salone","Parcheggio privato"]', '["Maggiordomo","Governante giornaliera","Concierge dedicato","Utenze e climatizzazione"]', '["Chef privato (su richiesta)","Motoscafo con skipper (su richiesta)","Transfer da\/per Milano"]', '["Check-in riservato dalle ore 16:00 con Welcome Concierge in villa","Check-out entro le ore 11:00 (late check-out su richiesta)","Eventi privati o ricevimenti consentiti solo previa autorizzazione scritta","Staff giornaliero discreto incluso secondo gli orari concordati"]', '{"bedrooms":5,"beds":6,"bathrooms":5,"maxGuests":10,"sqm":400,"pool":true,"seaView":false,"staff":["Maggiordomo","Governante","Giardiniere"],"chefAvailable":true,"depositAmount":6500,"rating":4.8,"reviewsCount":20,"locality":"Varenna"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('11', 'au-01', 'ferrari-sf90-stradale', 'auto', '1', 'costa-smeralda', '5', 'Ferrari SF90 Stradale', '1000 CV · Automatico · 2 posti', 'Porto Cervo, Costa Smeralda', '1600', 'giorno', '2', '2 posti', '1', '1', 'CONSEGNA INCLUSA', 'Supercar & Spider', '9.552', '41.13', '55', '38', 'L''ibrida più potente mai prodotta a Maranello: 1.000 cavalli, trazione integrale e uno scatto 0-100 in 2,5 secondi. La SF90 Stradale trasforma la litoranea della Gallura in un''esperienza da pista.

Consegnata a domicilio in tutta la Costa Smeralda con serbatoio pieno, briefing tecnico personale e assistenza dedicata 24/7 per l''intera durata del noleggio.', 'Cancellazione gratuita fino a 7 giorni dall''inizio; entro 7 giorni trattenuto il 30% a copertura del fornitore.', '["/images/products/ferrari-sf90-stradale/1.webp","/images/products/ferrari-sf90-stradale/2.webp","/images/products/ferrari-sf90-stradale/3.webp","/images/products/ferrari-sf90-stradale/4.webp"]', '["1.000 CV ibridi","Modalità eDrive silenziosa","Apple CarPlay","Telecamere 360°","Sollevatore anteriore","Interni in pelle Poltrona Frau"]', '["Consegna e ritiro a domicilio","Assicurazione Kasko con franchigia","Assistenza stradale dedicata 24\/7","100 km al giorno inclusi"]', '["Carburante","Km extra (€4\/km)","Autista (su richiesta)"]', '["Età minima del conducente: 25 anni, patente da almeno 5 anni","Secondo conducente incluso senza costi aggiuntivi","Divieto di fumo a bordo","Carburante: riconsegna con lo stesso livello del ritiro"]', '{"make":"Ferrari","model":"SF90 Stradale","year":2024,"seats":2,"transmission":"Automatico","fuelType":"Ibrido plug-in","horsepower":1000,"kmIncluded":100,"deliveryIncluded":true,"autoType":"Supercar","depositAmount":10000,"rating":4.9,"reviewsCount":18,"locality":"Porto Cervo","power":"1000 CV"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('12', 'au-02', 'lamborghini-huracan-evo-spyder', 'auto', '1', 'costa-smeralda', '5', 'Lamborghini Huracán Evo Spyder', '640 CV · Automatico · 2 posti', 'Porto Cervo, Costa Smeralda', '1400', 'giorno', '2', '2 posti', '1', '1', 'CABRIO', 'Supercar & Spider', '9.531', '41.141', '60', '50', 'Il V10 aspirato più iconico di Sant''Agata, a cielo aperto: 640 cavalli e un sound che riecheggia tra le curve del Pevero. La Spyder è l''auto simbolo delle estati in Costa Smeralda.

Capote elettrica in 17 secondi, quattro ruote sterzanti e modalità di guida ANIMA per adattare l''auto dal lungomare alla statale di montagna.', 'Cancellazione gratuita fino a 7 giorni dall''inizio; entro 7 giorni trattenuto il 30% a copertura del fornitore.', '["/images/products/lamborghini-huracan-evo-spyder/1.webp","/images/products/lamborghini-huracan-evo-spyder/2.webp","/images/products/lamborghini-huracan-evo-spyder/3.webp","/images/products/lamborghini-huracan-evo-spyder/4.webp"]', '["V10 aspirato 640 CV","Capote elettrica","Quattro ruote sterzanti","Apple CarPlay","Freni carboceramici","Interni in Alcantara"]', '["Consegna e ritiro a domicilio","Assicurazione Kasko con franchigia","100 km al giorno inclusi"]', '["Carburante","Km extra (€4\/km)","Pulizia straordinaria"]', '["Età minima del conducente: 25 anni, patente da almeno 5 anni","Secondo conducente incluso senza costi aggiuntivi","Divieto di fumo a bordo","Carburante: riconsegna con lo stesso livello del ritiro"]', '{"make":"Lamborghini","model":"Huracán Evo Spyder","year":2023,"seats":2,"transmission":"Automatico","fuelType":"Benzina","horsepower":640,"kmIncluded":100,"deliveryIncluded":true,"autoType":"Supercar","depositAmount":9000,"rating":4.8,"reviewsCount":25,"locality":"Porto Cervo","power":"640 CV"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('13', 'au-03', 'range-rover-autobiography', 'auto', '1', 'costa-smeralda', '6', 'Range Rover Autobiography', '350 CV · Automatico · 5 posti', 'Olbia, Costa Smeralda', '900', 'giorno', '5', '5 posti', '0', '1', NULL, 'SUV & Gran Turismo', '9.517', '40.925', '72', '58', 'L''ammiraglia britannica nella configurazione più raffinata: sedili executive posteriori, frigo bar e insonorizzazione totale. Perfetta per famiglie ed equipaggi che si muovono tra ville, porto e aeroporto.

Disponibile anche con autista NCC convenzionato per trasferimenti ed escursioni sull''isola.', 'Cancellazione gratuita fino a 7 giorni dall''inizio; entro 7 giorni trattenuto il 30% a copertura del fornitore.', '["/images/products/range-rover-autobiography/1.webp","/images/products/range-rover-autobiography/2.webp","/images/products/range-rover-autobiography/3.webp","/images/products/range-rover-autobiography/4.webp"]', '["Sedili executive posteriori","Frigo bar","Tetto panoramico","Sound system Meridian","Sospensioni pneumatiche","7 posti disponibili"]', '["Consegna in aeroporto Olbia","Assicurazione Kasko con franchigia","200 km al giorno inclusi"]', '["Carburante","Autista (su richiesta)","Seggiolini bimbi"]', '["Età minima del conducente: 25 anni, patente da almeno 5 anni","Secondo conducente incluso senza costi aggiuntivi","Divieto di fumo a bordo","Carburante: riconsegna con lo stesso livello del ritiro"]', '{"make":"Land Rover","model":"Range Rover Autobiography","year":2024,"seats":5,"transmission":"Automatico","fuelType":"Diesel mild-hybrid","horsepower":350,"kmIncluded":200,"deliveryIncluded":true,"autoType":"SUV","depositAmount":5000,"rating":4.7,"reviewsCount":40,"locality":"Olbia","power":"350 CV"}', '2026-11-03 12:32:25', '2026-11-03 12:32:25');
INSERT INTO `products` (`id`, `code`, `slug`, `category`, `destination_id`, `destination_slug`, `supplier_id`, `title`, `subtitle`, `location`, `price`, `unit`, `capacity`, `capacity_label`, `featured`, `is_available`, `badge`, `subtype`, `lng`, `lat`, `map_x`, `map_y`, `description`, `cancellation_policy`, `images_json`, `amenities_json`, `services_included_json`, `services_excluded_json`, `rules_json`, `specs_extra_json`, `created_at`, `updated_at`) VALUES ('14', 'au-04', 'porsche-911-turbo-cabrio', 'auto', '2', 'costiera-amalfitana', '7', 'Porsche 911 Turbo Cabriolet', '580 CV · Automatico · 4 posti', 'Positano, Costiera Amalfitana', '1100', 'giorno', '4', '4 posti', '1', '1', 'CABRIO', 'SUV & Gran Turismo', '14.48', '40.627', '26', '42', 'La 911 Turbo scoperta è la compagna ideale della statale amalfitana: compatta quanto basta per i tornanti, potente da riempire i rettilinei sul mare con i suoi 580 cavalli.

